def make_patch(patch_type, patch_size):
    if patch_type == 'white':
        return torch.full((3, patch_size, patch_size), 255, dtype=torch.uint8)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, patch_size, patch_size, dtype=torch.uint8)
        for i_p in range(patch_size):
            for j_p in range(patch_size):
                val = 255 if (i_p + j_p) % 2 == 0 else 0
                patch[:, i_p, j_p] = val
        return patch
    elif patch_type == 'random':
        return torch.randint(0, 2, (3, patch_size, patch_size), dtype=torch.uint8) * 255

